function useSentence(set, kind, u, who){
  const nm = list => list.map(it => esc(itemName(it)));
  const v = (lead, third) => (who ? '<b class="m">' + esc(who) + '</b> ' : '') + '<b class="uv" role="button" tabindex="0" data-rule="Select Weapons">' + (who ? third : lead) + '</b>';
  if(kind === 'ranged'){
    const cq = set.filter(isCQ), rest = set.filter(it => !isCQ(it)), big = hasKw(u, 'Monster') ? 'MONSTER' : hasKw(u, 'Vehicle') ? 'VEHICLE' : '';
    if(cq.length && rest.length && !big)
      return v('Pick one to shoot:', 'picks one to shoot:') + ' ' + orList(nm(cq)) + ' <b>or</b> ' + (rest.length > 1 ? 'all of ' : '') + andList(nm(rest)) + '.';
    const guns = modelCount(u) === 1 ? set.reduce((t, it) => t + (+it.n || 1), 0) : set.length;   // a Forgefiend's 2 Hades + 1 cannon: all of these
    const w = guns === 2 ? 'both' : 'all of these';
    return v('Shoots with ' + w, 'shoots with ' + w) + (cq.length && rest.length ? ' (a ' + big + ' fires its pistol too)' : '') + '.';
  }
  const ea = set.filter(isEA), other = set.filter(it => !isEA(it));
  const extra = ea.length ? ', <b>plus</b> ' + andList(nm(ea)) + ' on top (extra attacks)' : '';
  if(other.length > 1) return v('Pick one to fight with:', 'picks one to fight with:') + ' ' + orList(nm(other)) + extra + '.';
  if(other.length === 1){ const w = ea.length === 1 ? 'both' : 'all of these'; return v('Fights with ' + w + ':', 'fights with ' + w + ':') + ' ' + nm(other)[0] + extra + '.'; }
  return v('Fights with all of these', 'fights with all of these') + ' (extra attacks).';
}

function useLine(items, kind, u, part){
  if(items.length < 2 || !u.gear) return '';
  // in an attached unit, the first models line is the leader and the rest the bodyguard
  const own = i => part == null || (part === 0 ? i === 0 : i > 0);
  const lines = u.gear.map((g, i) => ({ i, who:u.models[i].replace(/^\d+× /, ''), set:items.filter(it => g.includes(itemName(it))) })).filter(l => l.set.length && own(l.i));
  const multi = lines.filter(l => l.set.length > 1);
  // a weapon only one model has, in a squad of mixed loadouts: name that model (the champion's pistol)
  if(lines.length > 1) for(const it of items){ const ls = lines.filter(l => l.set.includes(it)); if(!it.n && !it.carrier && ls.length === 1 && /^1× /.test(u.models[ls[0].i])) it.carrier = ls[0].who.replace(/ w\/.*$/, ''); }
  if(!multi.length){
    if(lines.length < 2) return '';
    for(const l of lines) for(const it of l.set) if(!it.n) it.carrier = l.who.replace(/ w\/.*$/, '');   // name the one model that has it
    return '<p class="use"><b class="m">One of these per model</b> · ×N = how many models have it.</p>';
  }
  const key = l => l.set.map(itemName).join('|');
  const kinds = [...new Map(multi.map(l => [key(l), l])).values()];
  if(kinds.length === 1 && multi.length === lines.length) return '<p class="use">' + useSentence(kinds[0].set, kind, u) + '</p>';
  const said = kinds.map(l => useSentence(l.set, kind, u));
  const others = multi.length < lines.length;
  if(kind === 'ranged' && said.every(x => /data-rule="Select Weapons">Shoots with/.test(x)))
    return '<p class="use"><b class="uv" role="button" tabindex="0" data-rule="Select Weapons">Every model shoots with all its guns</b>' + (others ? ' (see ×)' : '') + '.</p>';
  return kinds.map(l => '<p class="use">' + useSentence(l.set, kind, u, l.who.replace(/ w\/.*$/, '')) + '</p>').join('') +
    (others ? '<p class="use"><b class="m">The others:</b> one each (×N = how many models have it).</p>' : '');
}

function unitMods(u, kind){
  const det = unitDetRules(u).filter(r => r.mod).map(r => Object.assign({ from:r.name, rule:r.name }, singleMod(r.mod, u)));
  const lance = [...new Set((u.melee || []).filter(w => w.kw.some(k => /^lance/i.test(k))).map(w => w.group || w.name))];
  if(lance.length) det.push({ kind:'melee', when:'Made a charge move this turn', note:andList(lance) + ' +1 to wound', from:'Lance', rule:'Lance' });
  if(hasKw(u, 'Towering') && D.rules['Plunging Fire']) det.push({ kind:'ranged', when:'Target within 12" with models on ground level', note:'+1 BS', from:'Plunging Fire', rule:'Plunging Fire' });
  const strat = allStratagems().filter(s => s.mod && eligible(s).includes(u)).map(s => Object.assign({ from:s.name, strat:s.id, cp:s.cp }, s.mod));
  return (u.mods || []).concat(det, auraMods(u), strat).filter(m => m.kind === kind || m.kind === 'all');
}

function defenceItems(u, ph){
  const out = [];
  for(const r of u.rules){ const m = /^feel no pain (\d\+)/i.exec(r); if(m) out.push({ t:'Feel No Pain ' + m[1], a:'rule', v:r }); }
  for(const r of unitDetRules(u)) if(r.def && !out.some(x => x.t === r.def)) out.push({ t:r.def, a:'rule', v:r.name });   // e.g. Knights of Legend: FNP 6+
  for(const ab of u.abilities) if(ab.def && !naReason(ab) && !(ph && ab.defPh && !ab.defPh.includes(ph))) out.push({ t:ab.def, a:'ability', v:abilityKey(ab) });
  for(const s of allStratagems()) if(s.def && eligible(s).includes(u) && !(ph && !s.phases.includes(ph))) out.push({ t:s.cp + 'CP ' + s.name + ': ' + s.def, a:'strat', v:s.id });
  const weak = u.stats.filter(s => !/^[2-5]\+$/.test(s.InSv));
  if(weak.length && u.rules.includes('Waaagh!'))
    out.push({ t:'Riled up: 5+ INV' + (weak.length < u.stats.length ? ' (' + weak.map(s => s.name.replace(/ ×\d+$/, '')).join(', ') + ')' : ''), a:'rule', v:'Waaagh!' });
  return out;
}

const onceTag = ab => {
  const t = ab.text || '';
  for(const src of [ab.tag || '', (/\((once per [^)]+)\)/i.exec(t) || [])[1] || '', (/^once per [^,.]+(, per (army|unit))?/i.exec(t) || [])[0] || '']){
    const m = /once per (battle round|battle|phase|turn)(, per (army|unit))?/i.exec(src);
    if(m) return m[0].replace(/^o/, 'O');
  }
  return '';
};

function matches(n, u){
  if(!n) return true;
  if(n.all && !n.all.every(k => hasKw(u, k))) return false;
  if(n.any && !n.any.some(k => hasKw(u, k))) return false;
  if(n.none && n.none.some(k => hasKw(u, k))) return false;
  if(n.unless && matches(n.unless, u)) return false;
  return true;
}

function inertRule(name){
  const r = faction().armyRules.find(x => x.name === name);
  return !!(r && r.needs && !army().units.some(u => matches(r.needs, u)));
}

function auraMods(u){
  const out = [];
  for(const src of army().units) for(const m of src.aura || []){
    const self = src === u;
    if((self && m.notSelf) || !matches(m.needs, u)) continue;
    out.push(Object.assign({}, m, { when:self && m.selfWhen ? m.selfWhen : m.when, src }));
  }
  return out;
}

function phaseItems(){
  const out = [], f = faction(), units = army().units;
  for(const r of f.armyRules) if(r.ph && !inertRule(r.name)) out.push({ name:r.name, text:r.text, note:r.note, table:r.table, tag:r.tag, ph:r.ph, turn:r.turn, turns:r.turns, sub:f.name + ' army rule', units:[] });
  for(const d of detachments()) if(d.rule && d.rule.ph){
    const us = units.filter(u => matches(d.rule.needs, u));
    if(us.length) out.push({ name:d.rule.name, text:d.rule.text, note:d.rule.note, tag:d.rule.tag, table:d.rule.table, ph:d.rule.ph, turn:d.rule.turn, turns:d.rule.turns, sub:d.name + ' rule · ' + unitNames(us), units:us });
  }
  for(const u of units) for(const ab of u.abilities){
    if(!ab.ph || naReason(ab)) continue;
    const key = ab.name + '|' + ab.text;
    let e = out.find(x => x.key === key);
    if(!e){ e = { key, name:ab.name, text:ab.text, tag:ab.tag, ph:ab.ph, turn:ab.turn, turns:ab.turns, units:[] }; out.push(e); }
    e.units.push(u);
  }
  for(const [key, when] of Object.entries(CORE_PHASED)){
    const us = units.filter(u => unitRules(u).some(r => ruleKey(r) === key) || [...(u.ranged || []), ...(u.melee || [])].some(w => w.kw.some(k => ruleKey(k) === key)));
    if(us.length && D.rules[key]) out.push(Object.assign({ name:key, text:D.rules[key], sub:'Core rule · ' + unitNames(us), units:us }, when));
  }
  for(const e of out) if(!e.sub) e.sub = unitNames(e.units);
  return out;
}

const suits = (s, u) => keywordGated(s) || u.abilities.some(ab => (ab.text || '').toLowerCase().includes(s.name.toLowerCase() + ' stratagem')) ||
  (s.id === 'fire-overwatch' && (u.ranged || []).length > 0) ||
  (s.id === 'rapid-ingress' && (unitRules(u).some(r => ruleKey(r) === 'Deep Strike') || u.abilities.some(ab => /strategic reserves/i.test(ab.text))));

function proxyLines(u){
  const lines = u.models.map((m, i) => Object.assign(lineParts(m), { gear:(u.gear || [])[i] || [], base:baseOf(u, lineParts(m).name) }));
  const tag = [u.warlord ? 'Warlord' : '', u.enhancement].filter(Boolean);
  const own = (l, words) => [l.name === u.name || !u.short ? baseName(l.name) : u.short].concat(words).join(' · ');
  if(lines.length === 1 && lines[0].n === 1) return [Object.assign(lines[0], { mark:own(lines[0], tag), lead:true })];
  const body = u.leads ? lines.slice(1) : lines;
  if(u.leads) Object.assign(lines[0], { mark:own(lines[0], tag), lead:true });
  const std = body.slice().sort((x, y) => y.n - x.n)[0];
  for(const l of body){
    if(l === std){ l.mark = 'standard'; l.std = true; continue; }
    const sb = baseName(std.name), lb = baseName(l.name);
    const named = lb === sb ? '' : lb.startsWith(sb + ' ') ? lb.slice(sb.length + 1) : lb;
    const more = l.gear.filter(g => !std.gear.includes(g));
    l.mark = [named, more.join(' + '), l.extra].filter(Boolean).join(' · ') || 'standard';
  }
  return lines;
}
